import { RendererCanvas } from './base/RendererCanvas';
import { Vector3, fieldComposite } from './base/Vector3';

export class Solution extends RendererCanvas {

	t = 0.0;

	x0=-300.0;
	x1=300.0;
	y0=-300.0;
	y1=300.0;

	rx=50;
	ry=50;

	constructor(id: string) {
		super(document.getElementById(id) as HTMLDivElement);
		this.ctx.translate(this.ctx.canvas.width * 0.5, this.ctx.canvas.height * 0.5);
		// this.clear = () => { return 0 }
		this.init();
	}
	public init() {

		this.start();
	}
	public render(ctx: CanvasRenderingContext2D): void {
		this.renderCFieldComposite(ctx)

	}
	public renderCFieldComposite(ctx: CanvasRenderingContext2D): void {	
		const dx =(this.x1 - this.x0)/(this.rx-1.0);
		const dy =(this.y1 - this.y0)/(this.ry-1.0);
	
		const mousep =new Vector3(this.m[0], this.m[1], 0.0);
		const p = new Vector3();
	

		for(let j=0; j<this.ry; ++j) {
			p.y=this.y0+j*dy;
			for(let i=0; i<this.rx; ++i) {
				p.x=this.x0+i*dx;
				
				const df=fieldComposite(p, mousep, 10, 20);
				const p1=Vector3.add(p, df);

				ctx.beginPath()
				ctx.moveTo(p.x, p.y)
				ctx.lineTo(p1.x, p1.y)
				ctx.stroke();
			}
		}

		this.t += 0.1;
	}
}
